const profile={goal:{type:'general_fitness'},available_days:['mon'],timezone:'Australia/Brisbane',restrictions:['Stored knee restriction'],benchmark:{level:'established',pace_seconds_per_km:360,weekly_distance_meters:18000,long_run_meters:7000,source:'Stored athlete facts',observed_at:'2026-10-09T00:00:00Z'}}
