test('WEB-REVIEW-025 changing cached plan while preview preparation waits cannot send departed plan request',async({page})=>{
 await mockSession(page);await page.addInitScript(()=>{const digest=crypto.subtle.digest.bind(crypto.subtle);let release!:()=>void;(window as any).__previewGate=new Promise<void>(resolve=>release=resolve);(window as any).__releasePreview=release;crypto.subtle.digest=async(...args:Parameters<typeof crypto.subtle.digest>)=>{await(window as any).__previewGate;return digest(...args)}});let requests=0
 await page.route('**/api/coaching/status',route=>route.fulfill({status:200,json:status}));for(const id of ['pending-a','pending-b']){await page.route(`**/api/plans/${id}`,route=>route.fulfill({status:200,json:{id,name:id,revision:2,activity_type:'running',status:'draft',start_date:'2026-11-01',end_date:'2026-12-01',metadata:{forecast:[]}}}));await page.route(`**/api/plans/${id}/schedule`,route=>route.fulfill({status:200,json:{sessions:[],schedule:null}}));await page.route(`**/api/coaching/programs/${id}`,route=>route.fulfill({status:200,json:{forecast:[],forecastApproved:false}}))}
 await page.route('**/api/coaching/plans/pending-b/undo-preview',route=>{requests++;return route.fulfill({status:409,json:{detail:'Departed request intercepted'}})})
 await page.goto('/plans/pending-a');await expect(page.getByRole('heading',{name:'Future plan changes'})).toBeVisible();await page.evaluate(()=>{history.pushState(null,'','/plans/pending-b');dispatchEvent(new PopStateEvent('popstate'))});await page.getByRole('button',{name:'Preview future undo',exact:true}).click();await page.getByLabel('Previous plan revision').fill('1');await page.getByRole('button',{name:'Prepare preview',exact:true}).click();await expect(page.getByRole('button',{name:'Preparing preview…',exact:true})).toBeDisabled();await page.goBack();await expect(page).toHaveURL(/pending-a$/);await page.evaluate(()=>(window as any).__releasePreview());await page.getByRole('button',{name:'Preview future undo',exact:true}).click();await expect(page.getByLabel('Previous plan revision')).toHaveValue('');await page.getByRole('button',{name:'Cancel without changes',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);expect(requests).toBe(0)
})
test('WEB-REVIEW-026 departed Coaching cannot submit a delayed same-account preview',async({page})=>{
 await mockSession(page);await page.route('**/api/coaching/status',route=>route.fulfill({status:200,json:status}));let posts=0;await page.route('**/api/coaching/program',route=>{posts++;return route.fulfill({status:409,json:{detail:'Departed preview intercepted'}})})
 await page.goto('/coach/');await expect(page.getByLabel('Benchmark source',{exact:true})).toHaveValue(profile.benchmark.source);await page.evaluate(()=>{const digest=crypto.subtle.digest.bind(crypto.subtle);let release!:()=>void;const gate=new Promise<void>(resolve=>release=resolve);(window as any).__releaseDigest=release;(window as any).__entered=false;(window as any).__completed=false;Object.defineProperty(crypto.subtle,'digest',{configurable:true,value:async(...args:any[])=>{(window as any).__entered=true;await gate;const value=await(digest as any)(...args);(window as any).__completed=true;return value}})});await page.getByRole('button',{name:'Preview program',exact:true}).click();await expect.poll(()=>page.evaluate(()=>(window as any).__entered)).toBe(true);await openMockNavigation(page);await page.getByRole('link',{name:'Plans',exact:true}).click();await expect(page).toHaveURL(/\/plans$/);await page.evaluate(()=>(window as any).__releaseDigest());await expect.poll(()=>page.evaluate(()=>(window as any).__completed)).toBe(true);await page.waitForTimeout(250);expect(posts).toBe(0);await expect(page.getByRole('dialog')).toHaveCount(0)
})
